import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group, PlaneGeometry, Mesh } from 'three/webgpu'; // or 'three'? but allowed import from 'three/webgpu' for classes
// Actually THREE classes can be imported from 'three/webgpu' as per constraint. We'll use that.
// For clarity: import { Group, PlaneGeometry, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, Vector3, Color } = THREE;

  const group = new Group();

  // Parse text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleItem = items.find(item => item.text === 'Pricing' || item.role === 'headline');
  const displayText = titleItem?.text || 'Pricing';
  // Use the given fontSize from config if available, else fallback to scale
  const fontSize = titleItem?.typography?.fontSize != null ? titleItem.typography.fontSize : 0.34; // headline scale

  // Create background plane (will be textured)
  const planeWidth = 5.0;
  const planeHeight = 1.2;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10', // surface placeholder
    side: THREE.DoubleSide, // might be needed
  });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load background texture
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = texture;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Pricing title texture load failed:', err);
    });
  }

  // Create title text
  const textColor = '#e8ecf2'; // paper
  const textMesh = ctx.fontAtlas.createText(displayText, {
    fontSize: fontSize,
    color: textColor,
    align: 'center',
  });
  // Position text in front of plane (z slight forward)
  textMesh.position.set(0, 0, 0.05);
  group.add(textMesh);

  // User data: handlers (none) and cleanup
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Dispose all children recursively
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });

    // Kill any GSAP timelines attached to this node (none here)
  };

  return group;
}
